const result = parseMaybe(row.result || row.jsonb_build_object || row.data || row);
if (!result || result.ok !== true) {
  const missing = result && result.missing_columns ? JSON.stringify(result.missing_columns) : "unknown";
  throw new Error("postgres_schema_missing_expected_columns: " + missing);
}
return [{ json: result.input }];

