    }
  }
  return value;
}

function parseResult(row) {
  const source = row.result || row.jsonb_build_object || row.data || row;
  const parsed = parseMaybe(source);
  if (parsed && parsed.result) {
    return parseMaybe(parsed.result);
  }
  return parsed;
}

function fail(code, details) {
  const error = new Error(code);
  error.details = details || null;
  throw error;
}

const row = items[0] && items[0].json ? items[0].json : {};
const result = parseResult(row);

if (!result || typeof result !== "object" || Array.isArray(result)) {
  fail("claim_result_must_be_object", { row });
}

const input = parseMaybe(result.input || {});
const claimedRow = parseMaybe(result.claimed_row || null);

if (result.lock_acquired !== true) {
  fail("github_executor_lock_not_acquired", { result });
}

if (result.claimed !== true || !claimedRow || typeof claimedRow !== "object") {
  fail("github_execution_request_not_claimed", { result });
}

if (!input || typeof input !== "object" || Array.isArray(input)) {
  fail("claim_input_missing_or_invalid", { result });
}

if (!input.workflow_run_id || claimedRow.workflow_run_id !== input.workflow_run_id) {
