function collectResponses(nodeName) {
  try {
    const rows = $items(nodeName);
    const out = [];

    for (const item of rows) {
      const value = item && item.json ? item.json : null;
      if (!value) continue;

      if (Array.isArray(value)) {
        out.push(...value);
        continue;
      }

      if (Array.isArray(value.data)) {
        out.push(...value.data);
        continue;
      }

      if (Array.isArray(value.body)) {
        out.push(...value.body);
        continue;
      }

      if (value.number && value.head && value.base) {
        out.push(value);
        continue;
      }
    }

    return out;
  } catch (error) {
    return [];
  }
}

function prBodyMatchesRequest(pr, context) {
  const body = String(pr && pr.body ? pr.body : "");
  return body.includes("workflow_run_id: " + context.workflow_run_id)
    && body.includes("request_id: " + context.request_id)
    && body.includes("base_sha: " + context.base_sha)
    && body.includes("repository_full_name: " + context.repository_full_name);
}

const context = $items("Validate Base and Prepare Branch")[0].json;
const createResponse = $items("Create Feature Branch")[0].json || {};
const branchRef = $items("Fetch Feature Branch Ref")[0].json || {};
const openPrRows = collectResponses("Fetch Open PRs For Branch");

const branchSha = branchRef && branchRef.object ? branchRef.object.sha : null;

if (!branchSha) {
  return [{
    json: failurePayload(
      context,
      "feature_branch_ref_missing_after_create",
      "Feature branch ref is missing after create/reuse attempt.",
      { createResponse, branchRef }
    )
  }];
}

const expectedRef = "refs/heads/" + context.branch_name;
const branchJustCreated = createResponse
  && createResponse.ref === expectedRef
  && createResponse.object
  && createResponse.object.sha === context.base_sha;

const matchingPr = openPrRows.find(pr =>
  pr
  && pr.head
  && pr.base
  && pr.head.ref === context.branch_name
  && pr.base.ref === context.base_branch
  && pr.state === "open"
) || null;

const matchingPrIsSameRequest = matchingPr ? prBodyMatchesRequest(matchingPr, context) : false;

if (branchJustCreated && branchSha === context.base_sha) {
  return [{
    json: {
      ...context,
      continue_text: "yes",
      mutation_required: true,
      mutation_required_text: "yes",
      existing_pr: matchingPr || null
    }
  }];
}

if (matchingPr && matchingPrIsSameRequest) {
  if (branchSha === context.base_sha) {
    return [{
      json: {
        ...context,
        continue_text: "yes",
        mutation_required: true,
        mutation_required_text: "yes",
        existing_pr: matchingPr,
        branch_collision_evidence: "same_request_pr_body"
      }
    }];
  }

  return [{
    json: {
      ...context,
      continue_text: "yes",
      mutation_required: false,
      mutation_required_text: "no",
      implementation_commit_sha: branchSha,
      existing_pr: matchingPr,
      pr_number: matchingPr.number,
      pr_url: matchingPr.html_url,
      latest_pr_head_sha: matchingPr.head && matchingPr.head.sha ? matchingPr.head.sha : branchSha,
      branch_collision_evidence: "same_request_pr_body"
    }
  }];
}

return [{
