function isTransientGithubError(response) {
  if (!response || !response.error) return false;
  const text = JSON.stringify(response.error);
  return text.includes("EAI_AGAIN")
    || text.includes("ENOTFOUND")
    || text.includes("ECONNRESET")
    || text.includes("ETIMEDOUT")
    || text.includes("502")
    || text.includes("503")
    || text.includes("504");
}

const context = $items("Decide Branch Mutation Mode")[0].json;
const commitResponse = items[0] && items[0].json ? items[0].json : {};

if (!context.implementation_commit_sha) {
  return [{
    json: failurePayload(
      context,
      "missing_reused_implementation_commit_sha",
      "Reused branch has no implementation commit SHA.",
      { commitResponse }
    )
  }];
}

if (isTransientGithubError(commitResponse)) {
  return [{
    json: retryPayload(
      context,
      "github_api_transient_error",
      "GitHub API transient error while fetching reused branch commit. Retry required.",
      { commitResponse }
    )
  }];
}

const treeSha = commitResponse.tree && commitResponse.tree.sha ? commitResponse.tree.sha : null;

if (!treeSha) {
  return [{
    json: failurePayload(
      context,
      "missing_reused_implementation_tree_sha",
      "Reused branch commit has no tree SHA.",
      { commitResponse }
    )
  }];
}

return [{
  json: {
    ...context,
